mapper.select:
SELECT c.course_id, c.title, u.nickname, c.price, c.image, c.summary, COALESCE(AVG(r.course_rating), 0) AS averageCourseRating FROM courses c JOIN users u ON c.user_id = u.id LEFT JOIN reviews r ON c.course_id = r.course_id
AND c.title LIKE CONCAT('%', #{searchQuery}, '%')
GROUP BY c.course_id LIMIT #{start}, #{end}
